export interface DexScreenerPair {
    chainId: string;
    dexId: string;
    url: string;
    pairAddress: string;
    baseToken: {
        address: string;
        name: string;
        symbol: string;
    };
    quoteToken: {
        address: string;
        name: string;
        symbol: string;
    };
    priceNative: string;
    priceUsd: string;
    txns: {
        m5: { buys: number; sells: number };
        h1: { buys: number; sells: number };
        h6: { buys: number; sells: number };
        h24: { buys: number; sells: number };
    };
    volume: {
        h24: number;
        h6: number;
        h1: number;
        m5: number;
    };
    priceChange: {
        m5: number;
        h1: number;
        h6: number;
        h24: number;
    };
    liquidity?: {
        usd: number;
        base: number;
        quote: number;
    };
    fdv?: number;
    pairCreatedAt?: number;
}

export interface DexScreenerResponse {
    schemaVersion: string;
    pairs: DexScreenerPair[] | null;
}

export const dexscreener = {
    searchPairs: async (query: string): Promise<DexScreenerPair[]> => {
        try {
            // Rate limit handling could be added here if needed
            const response = await fetch(`https://api.dexscreener.com/latest/dex/search/?q=${query}`);

            if (!response.ok) {
                throw new Error('DexScreener API error');
            }

            const data: DexScreenerResponse = await response.json();
            return data.pairs || [];
        } catch (error) {
            console.error("Failed to fetch from DexScreener:", error);
            return [];
        }
    }
};
